text:
{
  "summary": "Adopt a dedicated, fail-closed Authorization Ledger daemon with OS-enforced role separation, transactional SQLite/WAL state, privileged canonical evidence import, exact-bound human R3 grants, and a persistent monotonic stopEpoch. V1C stores ALLOW_ONCE state but exposes no production effect-consumption path; any V1D consumer requires a separate ADR.",
  "payload": {
    "architecture": {
      "service": "authledgerd",
      "separation": "A standalone process structurally and operationally separate from Publication Broker and all execution-tier components.",
      "os_identity": {
        "user": "mihver-ledger",
        "group": "mihver-ledger",
        "interactive_login": false,
        "supplementary_groups": [],
        "service_manager": "Root-owned unit starts authledgerd with User=mihver-ledger, Group=mihver-ledger, NoNewPrivileges, private temporary directories, a read-only executable tree, and write access only to /var/lib/mihver/auth-ledger and /run/mihver/auth-ledger.",
        "trusted_tcb": [
          "kernel",
          "root/service manager",
          "authledgerd binary and root-owned configuration",
          "SQLite"
        ]
      },
      "filesystem": {
        "state_directory": "/var/lib/mihver/auth-ledger",
        "state_directory_mode": "0700 mihver-ledger:mihver-ledger",
        "database": "ledger.sqlite3, mode 0600 mihver-ledger:mihver-ledger",
        "binary_and_config": "root-owned and non-writable by mihver-ledger or any caller",
        "socket_directory": "/run/mihver/auth-ledger, mode 0750 root:mihver-ledger"
      }
    },
    "ipc_and_capabilities": {
      "peer_authentication": "Every accepted Unix-domain connection is authorized from kernel SO_PEERCRED UID/GID. Caller-supplied identity or role fields are ignored. Authorization is checked again per RPC.",
      "client_socket": {
        "path": "/run/mihver/auth-ledger/client.sock",
        "mode": "0660 mihver-ledger:mihver-ledger-client",
        "allowed_operations": [
          "getGrant",
          "listGrantMetadata",
          "validateGrantWithoutConsumption",
          "getStopEpoch",
          "getCouncilEpoch",
          "getAuditReceipt"
        ],
        "forbidden_operations": [
          "issueGrant",
          "revokeGrant",
          "importEvidence",
          "mutateCouncilRegistry",
          "incrementStopEpoch",
          "checkAndConsume"
        ]
      },
      "admin_sockets": [
        {
          "path": "/run/mihver/auth-ledger/grant-admin.sock",
          "mode": "0660 mihver-ledger:mihver-r3-grant-admin",
          "authorized_role": "human R3 grant administrators",
          "operations": [
            "issueGrant",
            "revokeGrant"
          ]
        },
        {
          "path": "/run/mihver/auth-ledger/evidence-import.sock",
          "mode": "0660 mihver-ledger:mihver-evidence-importer",
          "authorized_role": "dedicated evidence importer",
          "operations": [
            "importCanonicalEvidence"
          ]
        },
        {
          "path": "/run/mihver/auth-ledger/registry-admin.sock",
          "mode": "0660 mihver-ledger:mihver-council-registry-admin",
          "authorized_role": "trusted Council registry administrator",
          "operations": [
            "installCouncilEpoch",
            "retireCouncilEpoch"
          ]
        },
        {
          "path": "/run/mihver/auth-ledger/stop-admin.sock",
          "mode": "0660 mihver-ledger:mihver-stop-operator",
          "authorized_role": "global-stop operator",
          "operations": [
            "incrementStopEpoch"
          ]
        }
      ],
      "role_isolation": "The four privileged groups have no implicit cross-membership. authledgerd maps each socket to a compile-time RPC allowlist and also validates peer credentials, so access to one administrative socket grants no other capability.",
      "ai_exclusion": "Claude, Codex, their service accounts, and their worker processes are members only of mihver-ledger-client when read access is required. They are never members of any privileged group, receive no privileged socket file descriptor, and cannot issue grants, import trusted evidence, mutate the Council registry, or change stopEpoch."
    },
    "storage_and_transactions": {
      "engine": "SQLite with WAL, foreign_keys=ON, synchronous=FULL, trusted_schema=OFF, defensive mode enabled, and a single authledgerd writer.",
      "write_rule": "Every state mutation and its audit event commit in the same BEGIN IMMEDIATE transaction. Failed commits produce neither state nor success receipts.",
      "audit": "Append-only audit rows include transaction ID, authenticated peer UID, authorized role, operation, canonical request digest, prior and resulting state identifiers, timestamp, and result. UPDATE and DELETE are denied for audit rows by application invariants and startup schema verification."
    },
    "council_and_evidence_boundary": {
      "registry": "CouncilEpochRegistry is stored inside the ledger database and contains epoch ID, exact member/key set, signature policy, activation state, canonicalization version, and registry-record digest.",
      "registry_authority": "Only registry-admin.sock may mutate it. Grant administrators, evidence importers, clients, Publication Broker, Claude, and Codex cannot do so.",
      "import": "The evidence importer submits original supported evidence bytes plus declared media type and provenance metadata. authledgerd performs bounded parsing, schema validation, canonicalization, Council-epoch lookup, signature/quorum validation, replay checks, and digest computation itself.",
      "trust_rule": "A caller-supplied digest, parsed object, approval flag, signer list, or hash-shaped artifact is never trusted as evidence. Unsupported, ambiguous, non-canonical, unknown-epoch, expired, or invalidly signed evidence is rejected and audited.",
      "stored_result": "Accepted evidence stores immutable original-byte digest, canonical-byte digest, canonicalization version, validated Council epoch, verified signer identities, validation result, and import transaction ID."
    },
    "authorization_grants": {
      "issuer": "Only an authenticated human R3 administrator using grant-admin.sock may create or revoke a grant.",
      "required_binding": [
        "grantId",
        "subject identity",
        "operation code",
        "exact target/resource digest",
        "exact canonical evidence digest",
        "Council epoch and registry-record digest",
        "issuance stopEpoch",
        "notBefore and expiresAt",
        "ALLOW_ONCE disposition",
        "issuer peer UID",
        "issuance transaction ID"
      ],
      "issuance_checks": "Issuance requires already-imported valid evidence, an active matching Council epoch, current stopEpoch capture inside the same write transaction, bounded validity, uniqueness of grantId, and no wildcard subject, operation, target, evidence, or epoch fields.",
      "validation": "A grant is valid only when every requested binding matches exactly, time bounds hold, evidence and Council epoch remain acceptable, the grant is not revoked, and grant.issuanceStopEpoch equals the current global stopEpoch.",
      "consume_once_state": "The ledger schema may record unused/consumed status and a unique consumption transaction for ALLOW_ONCE, but V1C has no callable production checkAndConsume endpoint and no component may use this state to trigger or authorize an effect."
    },
    "stop_epoch": {
      "owner": "authledgerd is the sole database writer; mutation authority is exclusively the OS role mihver-stop-operator through stop-admin.sock.",
      "representation": "A singleton row keyed by the fixed name GLOBAL_STOP with an unsigned 64-bit epoch, schema version, and last mutation transaction ID. Missing rows, duplicates, invalid types, overflow, or values outside range are fatal.",
      "increment": "authledgerd executes BEGIN IMMEDIATE; reads the singleton; rejects UINT64_MAX; updates epoch to exactly old+1 using a guarded WHERE epoch=old clause; inserts the audit row; commits; then returns the committed epoch. Concurrent requests serialize on SQLite's writer lock, and a zero-row guarded update is retried or rejected without success.",
      "persistence": "The committed value resides in ledger.sqlite3 and WAL under synchronous=FULL. Startup completes WAL recovery, verifies schema and singleton cardinality, runs integrity checks, and reads stopEpoch before opening any socket.",
      "corruption_or_ambiguity": "On integrity failure, unreadable WAL, missing or ambiguous singleton state, unauthorized file ownership/mode, or uncertain recovery, authledgerd opens no sockets and enters global-stop failure. It never guesses, resets, or recreates the register. Recovery is an offline root-controlled incident procedure using preserved database/WAL material and audited backups; service resumes only with a demonstrably non-decreasing epoch. If the prior high-water value cannot be established, the ledger remains unavailable rather than selecting a value.",
      "stale_rejection": "All grant issuance records the epoch read transactionally. Every later validation rejects when issuanceStopEpoch differs from current stopEpoch, so one increment invalidates every earlier grant.",
      "no_reset_path": "There is no decrement, set, reset, delete, import, database-reinitialize, or epoch-override RPC. Neither ADMIN nor CLIENT protocols define such an operation. SQLite files are inaccessible to normal administrators and clients; only the daemon OS user can write them, while root is explicitly part of the machine TCB."
    },
    "zero_execution_effect_consumers": {
      "v1c_invariant": "At V1C exit, no production execution-tier component, Publication Broker, agent, plugin, worker, or client calls checkAndConsume or consumes ALLOW_ONCE state to perform any external or local effect.",
      "enforcement": "checkAndConsume is absent from all installed V1C socket dispatch tables and client libraries. Build/deployment tests reject that RPC symbol or an execution dependency on authledgerd outside read-only validation and observability paths.",
      "dormant_future_interface": "A non-installed interface specification may reserve atomic checkAndConsume semantics, but it has no socket route, credentials, caller, deployment unit, or effect binding in V1C. Enabling any V1D consumer requires a separate ADR covering consumer identity, effect binding, crash semantics, replay behavior, and rollout."
    }
  }
}
